window.__code__["code-w12-governed-agents-py"] = {"code_id": "code-w12-governed-agents-py", "kind": "local", "title": "governed_agents.py", "source_path": "/Users/zhongyou/Desktop/2027年/code/w12/governed_agents.py", "highlight_line": null, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># code/w12/governed_agents.py</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\"><span class=\"c-com\"># W12 作业1:在 W11 骨架上加 Stop Gate(BudgetGate)治理 —— 防 Agent 烧钱</span></span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\"><span class=\"c-com\"># 对照 QwenPaw loop/gates/budget.py:27(BudgetGate) + token_usage/model_wrapper.py:15</span></span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\"><span class=\"c-com\"># 用 on_model_call 中间件累计 token,超预算就注入停止指令 + max_iters 兜底</span></span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\"><span class=\"c-com\"># 前置: export DASHSCOPE_API_KEY=\u00005\u0000</span></span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\"><span class=\"c-com\"># 运行:  python code/w12/governed_agents.py</span></span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\"><span class=\"c-com\"># 预期:  Agent 跑若干轮,token 达预算(BUDGET)时触发 BUDGET 警告并停止迭代</span></span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\"><span class=\"c-kw\">import</span> asyncio</span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\"><span class=\"c-kw\">import</span> os</span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\"><span class=\"c-kw\">from</span> typing <span class=\"c-kw\">import</span> AsyncGenerator, Callable</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.agent <span class=\"c-kw\">import</span> Agent, ReActConfig</span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.credential <span class=\"c-kw\">import</span> DashScopeCredential</span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.message <span class=\"c-kw\">import</span> UserMsg</span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.middleware <span class=\"c-kw\">import</span> MiddlewareBase</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.model <span class=\"c-kw\">import</span> DashScopeChatModel</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.tool <span class=\"c-kw\">import</span> Bash, Toolkit</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\"><span class=\"c-kw\">class</span> BudgetGate(MiddlewareBase):</span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;预算门控:累计 token 超预算就注入停止指令。</span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\">    对照 QwenPaw BudgetGate(budget.py:27)。真实版能熔断;教学版注入指令 + max_iters 兜底。</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> __init__(<span class=\"c-kw\">self</span>, budget: int = 4000) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>.budget = budget</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>.used = 0</span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> on_model_call(</span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">        agent: Agent,</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">        input_kwargs: dict,</span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">        next_handler: Callable[[], AsyncGenerator],</span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">    ) -&gt; AsyncGenerator:</span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">        <span class=\"c-kw\">async</span> <span class=\"c-kw\">for</span> item <span class=\"c-kw\">in</span> next_handler():</span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">            <span class=\"c-kw\">yield</span> item</span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">        <span class=\"c-com\"># 调用后累加 token(从最后一条消息的 usage 取)</span></span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">        last = agent.state.context[-1] <span class=\"c-kw\">if</span> agent.state.context <span class=\"c-kw\">else</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\">        u = getattr(last, <span class=\"c-str\">&quot;usage&quot;</span>, <span class=\"c-kw\">None</span>) <span class=\"c-kw\">if</span> last <span class=\"c-kw\">else</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> u:</span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\">            <span class=\"c-kw\">self</span>.used += getattr(u, <span class=\"c-str\">&quot;input_tokens&quot;</span>, 0) + getattr(u, <span class=\"c-str\">&quot;output_tokens&quot;</span>, 0)</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\">            print(f<span class=\"c-str\">&quot;   💰 累计 token: {self.used}/{self.budget}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> <span class=\"c-kw\">self</span>.used &gt; <span class=\"c-kw\">self</span>.budget:</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">                print(f<span class=\"c-str\">&quot;🛑 BUDGET 超限 {self.used}&gt;{self.budget},注入停止指令&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\">                agent.state.context.append(</span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">                    UserMsg(</span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\">                        <span class=\"c-str\">&quot;system&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">                        <span class=\"c-str\">&quot;&lt;system&gt;预算超限,请立即停止调用工具,用已有信息收尾回答。&lt;/system&gt;&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">                    )</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\"><span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> main() -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\">    model = DashScopeChatModel(</span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\">        credential=DashScopeCredential(api_key=os.environ[<span class=\"c-str\">&quot;DASHSCOPE_API_KEY&quot;</span>]),</span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\">        model=<span class=\"c-str\">&quot;qwen-plus&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\">        stream=<span class=\"c-kw\">True</span>,</span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\">    )</span></div>\n<div class=\"c-line\" data-line=\"61\"><span class=\"c-no\">61</span><span class=\"c-src\">    agent = Agent(</span></div>\n<div class=\"c-line\" data-line=\"62\"><span class=\"c-no\">62</span><span class=\"c-src\">        name=<span class=\"c-str\">&quot;governed&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"63\"><span class=\"c-no\">63</span><span class=\"c-src\">        system_prompt=<span class=\"c-str\">&quot;你是助手,需要时调工具查目录信息。&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"64\"><span class=\"c-no\">64</span><span class=\"c-src\">        model=model,</span></div>\n<div class=\"c-line\" data-line=\"65\"><span class=\"c-no\">65</span><span class=\"c-src\">        toolkit=Toolkit(tools=[Bash()]),</span></div>\n<div class=\"c-line\" data-line=\"66\"><span class=\"c-no\">66</span><span class=\"c-src\">        middlewares=[BudgetGate(budget=4000)],   <span class=\"c-com\"># 预算 4000 token(教学调小)</span></span></div>\n<div class=\"c-line\" data-line=\"67\"><span class=\"c-no\">67</span><span class=\"c-src\">        react_config=ReActConfig(max_iters=8),   <span class=\"c-com\"># max_iters 兜底</span></span></div>\n<div class=\"c-line\" data-line=\"68\"><span class=\"c-no\">68</span><span class=\"c-src\">    )</span></div>\n<div class=\"c-line\" data-line=\"69\"><span class=\"c-no\">69</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">for</span> e <span class=\"c-kw\">in</span> agent.reply_stream(</span></div>\n<div class=\"c-line\" data-line=\"70\"><span class=\"c-no\">70</span><span class=\"c-src\">        UserMsg(<span class=\"c-str\">&quot;u&quot;</span>, <span class=\"c-str\">&quot;统计当前目录各类文件数量,给出报告。&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"71\"><span class=\"c-no\">71</span><span class=\"c-src\">    ):</span></div>\n<div class=\"c-line\" data-line=\"72\"><span class=\"c-no\">72</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> e.type.value == <span class=\"c-str\">&quot;TEXT_BLOCK_DELTA&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"73\"><span class=\"c-no\">73</span><span class=\"c-src\">            print(e.delta, end=<span class=\"c-str\">&quot;&quot;</span>, flush=<span class=\"c-kw\">True</span>)</span></div>\n<div class=\"c-line\" data-line=\"74\"><span class=\"c-no\">74</span><span class=\"c-src\">    print(<span class=\"c-str\">&quot;\\n\\n✅ 完成。把 budget 调更小可观察更早触发熔断。&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"75\"><span class=\"c-no\">75</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"76\"><span class=\"c-no\">76</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"77\"><span class=\"c-no\">77</span><span class=\"c-src\"><span class=\"c-kw\">if</span> __name__ == <span class=\"c-str\">&quot;__main__&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"78\"><span class=\"c-no\">78</span><span class=\"c-src\">    asyncio.run(main())</span></div>\n</div>", "lines": 78, "explanation": "governed_agents.py 是本教程的可运行示例代码，示范对应周次核心概念；顶部注释含运行前置依赖与预期输出，建议结合左侧源码与对应周文档「动手作业」一起读。", "knowledge_points": [], "related_docs": ["W12-多Agent协作平台实战(下)-毕业交付"]};
